self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_VERSION).then((cache) => cache.addAll(APP_SHELL)).then(() => self.skipWaiting()),
  );
});
 
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => Promise.all(keys.filter((k) => k !== CACHE_VERSION).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});
 
self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
 
  const url = new URL(req.url);
  const isSameOrigin = url.origin === self.location.origin;
  // Navegação de verdade (abrir/recarregar a página, F5, digitar a URL) —
  // diferente do resto do app-shell (JS/CSS/libs), que é cache-first pra
  // abrir rápido e funcionar offline, ESTA aqui vai pra REDE primeiro. É a
  // peça que faltava pra "impedir que carregue uma página antiga em vez da
  // nova" sem depender só do navegador decidir sozinho quando checar o
  // Service Worker de novo (ver também `updateViaCache:'none'` e o
  // recarregamento automático em app.js `_registerServiceWorker`): com
  // internet, o HTML mais novo do servidor SEMPRE vence; só cai pro cache
  // (pra continuar funcionando offline) se a rede falhar de verdade.
  const isNavigation = isSameOrigin && (req.mode === 'navigate' || url.pathname === '/' || url.pathname.endsWith('/index.html'));
 
  if (isNavigation) {
    event.respondWith(
      fetch(req).then((res) => {
        if (res && res.ok) caches.open(CACHE_VERSION).then((c) => c.put(req, res.clone()));
        return res;
      }).catch(() => caches.match(req).then((cached) => cached || caches.match('./index.html'))),
    );
  } else if (isSameOrigin) {
    // App shell (incluindo lib/*, agora vendorizado): cache-first, atualiza em segundo plano
    event.respondWith(
      caches.match(req).then((cached) => {
        const fetchPromise = fetch(req).then((res) => {
          if (res && res.ok) caches.open(CACHE_VERSION).then((c) => c.put(req, res.clone()));
          return res;
        }).catch(() => cached);
        return cached || fetchPromise;
      }),
    );
  }
});